# Test chunk_documents
PYTHONPATH=/consumer/src REPOPROOF_ADAPTATION_DIR=/adaptation /venv/env/bin/python -c "
import sys
sys.path.insert(0, '/adaptation')
from adapter import chunk_documents
import json

request = {
    'documents': [
        {
            'document_id': 'd0',
            'text': 'Hello world. This is a test. Another sentence here.',
            'metadata': {'source': 'test'}
        },
        {
            'document_id': 'd1',
            'text': '   ',  # whitespace only
            'metadata': {}
        },
        {
            'document_id': 'd2',
            'text': 'Short doc.',
            'metadata': {}
        },
    ],
    'strategy': 'sentence',
    'chunk_size': 120
}
result = chunk_documents(request)
print(json.dumps(result, indent=2))
